let lookup_pair key arr =
  let rec go lo hi =
    if lo >= hi then None
    else
      let mid = (lo + hi) / 2 in
      let k = fst arr.(mid) in
      if k = key then Some arr.(mid)
      else if k < key then go (mid + 1) hi else go lo mid
  in
  go 0 (Array.length arr)

let decomposition_of cp =
  match lookup_pair cp decomposition with Some (_, xs) -> xs | None -> [| cp |]

let ccc cp =
  match lookup_pair cp combining_class with Some (_, n) -> n | None -> 0

let compose_pair a b =
  let rec go lo hi =
    if lo >= hi then None
    else
      let mid = (lo + hi) / 2 in
      let (x, y, z) = composition.(mid) in
      if x = a && y = b then Some z
      else if (x < a) || (x = a && y < b) then go (mid + 1) hi
      else go lo mid
  in
  go 0 (Array.length composition)

let utf8_decode s =
  let n = String.length s in
  let rec one i acc =
    if i = n then Some (List.rev acc)
    else
      let b i = Char.code s.[i] in
      let x = b i in
      let need, cp =
        if x < 0x80 then (0, x)
        else if x land 0xe0 = 0xc0 then (1, x land 0x1f)
        else if x land 0xf0 = 0xe0 then (2, x land 0x0f)
        else if x land 0xf8 = 0xf0 then (3, x land 0x07)
        else (-1, 0)
      in
      if need < 0 || i + need >= n then None
      else
        let rec tail j value =
          if j > need then Some value
          else
            let y = b (i + j) in
            if y land 0xc0 <> 0x80 then None
            else tail (j + 1) ((value lsl 6) lor (y land 0x3f))
        in
        match tail 1 cp with
        | None -> None
        | Some cp ->
            let valid =
              (need = 0) ||
              (need = 1 && cp >= 0x80) ||
              (need = 2 && cp >= 0x800 && not (cp >= 0xd800 && cp <= 0xdfff)) ||
              (need = 3 && cp >= 0x10000 && cp <= 0x10ffff)
            in
            if not valid then None else one (i + need + 1) (cp :: acc)
  in
  one 0 []

let utf8_encode cps =
  let b = Buffer.create (List.length cps * 2) in
  let add cp =
    if cp < 0x80 then Buffer.add_char b (Char.chr cp)
    else if cp < 0x800 then begin
      Buffer.add_char b (Char.chr (0xc0 lor (cp lsr 6)));
      Buffer.add_char b (Char.chr (0x80 lor (cp land 0x3f)))
    end else if cp < 0x10000 then begin
      Buffer.add_char b (Char.chr (0xe0 lor (cp lsr 12)));
      Buffer.add_char b (Char.chr (0x80 lor ((cp lsr 6) land 0x3f)));
      Buffer.add_char b (Char.chr (0x80 lor (cp land 0x3f)))
    end else begin
      Buffer.add_char b (Char.chr (0xf0 lor (cp lsr 18)));
      Buffer.add_char b (Char.chr (0x80 lor ((cp lsr 12) land 0x3f)));
      Buffer.add_char b (Char.chr (0x80 lor ((cp lsr 6) land 0x3f)));
      Buffer.add_char b (Char.chr (0x80 lor (cp land 0x3f)))
    end
  in
  List.iter add cps; Buffer.contents b

let rec decompose cp =
  Array.to_list (decomposition_of cp) |> List.concat_map (fun x ->
    if x = cp then [x] else decompose x)

let reorder cps =
  (* Keep each starter and its following combining sequence together, then
     stably sort marks by canonical combining class. *)
  let sort_marks marks =
    List.fold_left (fun acc cp ->
      let rec insert = function
        | [] -> [cp]
        | x :: xs as all ->
            if ccc x > ccc cp then cp :: all else x :: insert xs
      in
      insert acc) [] marks
  in
  let rec groups acc group = function
    | [] ->
        List.rev_append (List.rev group |> (function
          | [] -> []
          | starter :: marks -> starter :: sort_marks marks)) acc
        |> List.rev
    | cp :: rest when ccc cp = 0 && group <> [] ->
        let normalized =
          match List.rev group with
          | [] -> []
          | starter :: marks -> starter :: sort_marks marks
        in
        groups (List.rev_append normalized acc) [cp] rest
    | cp :: rest -> groups acc (cp :: group) rest
  in
  groups [] [] cps

let compose cps =
  let rec go out starter last_ccc = function
    | [] -> List.rev out
    | cp :: rest ->
        let cls = ccc cp in
        (match compose_pair starter cp with
         | Some combined when last_ccc < cls || last_ccc = 0 ->
             go out combined last_ccc rest
         | _ ->
             go (cp :: out) (if cls = 0 then cp else starter) cls rest)
  in
  match cps with
  | [] -> []
  | first :: rest -> go [first] first 0 rest

let nfc_normalize s =
  match utf8_decode s with
  | None -> s
  | Some cps ->
      cps |> List.concat_map decompose |> reorder |> compose |> utf8_encode
